// The avatar: a seated 32x48 figure with five looping activities and three
// status bubbles to its right. Pure drawing: pixels in, Raster cells out.
//
// The frames, their timing and the bubble tiles are the supplied artwork,
// embedded as text: one letter a pixel, '.' for nothing.

export type AvatarState = 'idle' | 'thinking' | 'writing' | 'computer' | 'agents'
/** What the bubbles show: how the last turn ended, subagents running, errors this turn. */
export type AvatarEvents = { outcome: 'done' | 'stopped' | null; agents: number; errors: number }

export const AVATAR_W = 32
export const AVATAR_H = 48
/** The strip to the figure's right the bubbles are drawn in. */
export const BUBBLE_W = 20
const TILE_H = 15

/** A Raster cell colour meaning "the panel's own". */
const EMPTY = 0x01000000

