/** Digits 0 to 9, three wide and five high, row by row. */
const DIGITS: readonly string[] = ['111101101101111', '010110010010111', '111001111100111', '111001011001111', '101101111001001', '111100111001111', '111100111101111', '111001010010010', '111101111101111', '111101111001111']

/** The frame `state` shows `t` ms into its loop. */
function frameAt(state: AvatarState, t: number): string {
  const loop = LOOPS[state]
  let left = Math.max(0, t) % loop.reduce((sum, step) => sum + step[1], 0)
  for (const [id, ms] of loop) {
    if (left < ms) return id
    left -= ms
  }
  return loop[0]?.[0] ?? ''
}

type Canvas = { px: Int32Array; w: number; h: number }
function pixel(g: Canvas, x: number, y: number, c: number): void {
  if (x >= 0 && x < g.w && y >= 0 && y < g.h) g.px[y * g.w + x] = c
}

/** One bubble with its top at row `top` of the strip, and its count if it has one. */
function bubble(g: Canvas, ox: number, top: number, kind: 'done' | 'stopped' | 'agent' | 'error', value?: number): void {
  const text = value === undefined ? '' : String(Math.min(99, value))
  const size = text.length === 2 ? 2 : 1
  const tile = TILES[`${kind}${size}`] ?? []
  tile.forEach((row, dy) => {
    for (let x = 0; x < BUBBLE_W; x++) {
      const c = BUBBLE_PALETTE[row[x] ?? '']
      if (c !== undefined) pixel(g, ox + x, top + dy, c)
    }
  })
  // The agent tile carries a picture on its left; the error tile's mark is narrower.
  const left = kind === 'agent' ? (size === 2 ? 12 : 14) : size === 2 ? 10 : 12
  for (let j = 0; j < text.length; j++) {
    const bits = DIGITS[Number(text[j])] ?? ''
    for (let i = 0; i < bits.length; i++) {
      if (bits[i] === '1') pixel(g, ox + left + j * 4 + (i % 3), top + 4 + Math.floor(i / 3), INK)
    }
  }
}

/** The three bubbles, each on its own rows and each drawn only while it has something to say. */
function bubbles(g: Canvas, ox: number, ev: AvatarEvents): void {
  if (ev.outcome !== null) bubble(g, ox, 1, ev.outcome)
  if (ev.agents > 0) bubble(g, ox, 17, 'agent', ev.agents)
  if (ev.errors > 0) bubble(g, ox, 33, 'error', ev.errors)
}

const cellCache = new Map<string, string>()

/** Forget the cells built so far (when the figure leaves the screen). */
export function clearAvatarCells(): void {
  cellCache.clear()
}

/** The key of one drawing: frame and bubbles. Equal keys, equal cells. */
export function avatarKey(state: AvatarState, t: number, ev: AvatarEvents | null): string {
  return `${frameAt(state, t)}|${ev === null ? '' : `${ev.outcome ?? ''},${Math.min(99, ev.agents)},${Math.min(99, ev.errors)}`}`
}

/**
 * The figure as Raster cells, `columns` wide and `AVATAR_H / 2` rows high:
 * each cell is two pixels, the upper as the glyph's colour and the lower as
 * its background. With `ev` the bubble strip is drawn to the right.
 */
export function avatarCells(state: AvatarState, t: number, ev: AvatarEvents | null): { cells: string; columns: number; rows: number } {
  const columns = AVATAR_W + (ev === null ? 0 : BUBBLE_W)
  const rows = AVATAR_H / 2
  const key = avatarKey(state, t, ev)
  let cells = cellCache.get(key)
  if (cells === undefined) {
    const g: Canvas = { px: new Int32Array(columns * AVATAR_H).fill(EMPTY), w: columns, h: AVATAR_H }
    const frame = FRAMES[frameAt(state, t)] ?? ''
    for (let y = 0; y < AVATAR_H; y++) {
      for (let x = 0; x < AVATAR_W; x++) {
        const c = PALETTE[frame[y * AVATAR_W + x] ?? '']
        if (c !== undefined) g.px[y * columns + x] = c
      }
    }
    if (ev !== null) bubbles(g, AVATAR_W, ev)
    const words = new Uint32Array(columns * rows * 3)
    let at = 0
    const put = (glyph: number, fg: number, bg: number) => {
      words[at++] = glyph
      words[at++] = fg
      words[at++] = bg
    }
    for (let y = 0; y < AVATAR_H; y += 2) {
      for (let x = 0; x < columns; x++) {
        const top = g.px[y * columns + x] ?? EMPTY
        const bottom = g.px[(y + 1) * columns + x] ?? EMPTY
        if (top === EMPTY && bottom === EMPTY) put(0x20, EMPTY, EMPTY)
        else if (top === EMPTY) put(0x2584, bottom, EMPTY) // ▄
        else put(0x2580, top, bottom) // ▀
      }
    }
    cells = (new Uint8Array(words.buffer) as unknown as { toBase64(): string }).toBase64()
    if (cellCache.size > 120) cellCache.clear()
    cellCache.set(key, cells)
  }
  return { cells, columns, rows }
}
